solution:
#include <map>
#include <optional>
#include <string>

std::optional<int> find_score(const std::map<std::string, int>& scores,
                              const std::string& name) {
    auto it = scores.find(name);
    if (it == scores.end()) return std::nullopt;
    return it->second;
}
